package com.library.controller;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.library.dto.BookCopyActionContracts.ConfirmRequest;
import com.library.dto.BorrowRequest;
import com.library.entity.*;
import com.library.service.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.*;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="MYSQL_TEST_URL",matches=".+")
@SpringBootTest(properties={"spring.flyway.enabled=true","spring.sql.init.mode=never","bootstrap.admin.username=admin","bootstrap.admin.password=StructuredSyntheticAdministrator123"})
class MySqlStructuredLocationControllerTest extends StructuredLocationControllerTest {
    @Autowired LocationMaintenanceService maintenance;@Autowired PlatformTransactionManager transactions;
    @DynamicPropertySource static void mysql(DynamicPropertyRegistry r){String url=System.getenv("MYSQL_TEST_URL");if(url==null||!url.matches("jdbc:mysql://127\\.0\\.0\\.1:33079/library_repair_tests(?:\\?.*)?"))throw new IllegalStateException("Owned disposable schema required");r.add("spring.datasource.url",()->url);r.add("spring.datasource.driver-class-name",()->"com.mysql.cj.jdbc.Driver");r.add("spring.datasource.username",()->System.getenv().getOrDefault("MYSQL_TEST_USER","root"));r.add("spring.datasource.password",()->System.getenv().getOrDefault("MYSQL_TEST_PASSWORD",""));}
    @BeforeEach void roles(){for(String[] role:new String[][]{{"admin","ADMIN"},{"librarian","LIBRARIAN"},{"reader","READER"}})if(countFor("sys_user","username=?",role[0])==0)jdbc.update("INSERT INTO sys_user(username,password,real_name,role,status) VALUES (?,'synthetic-only','合成结构化验收',?,1)",role[0],role[1]);}
    @Override protected void installFailure(){jdbc.execute("CREATE TRIGGER copy_action_fail BEFORE UPDATE ON book_copy_action_request FOR EACH ROW BEGIN IF NEW.state='COMMITTED' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic-action-audit-failure';END IF;END");}
    @Test void renameAndMoveInBothCommitOrdersProduceOnlyValidSerialResults()throws Exception{
        for(boolean renameFirst:List.of(true,false)){Address a=address();Book b=book(1,1);BookCopy c=copy(b,"AVAILABLE",null);ObjectNode r=move(c,a.id());JsonNode p=preview2(r);ObjectNode edit=shelfEdit(a.shelf(),"并发新名称");Callable<Object> move=()->commit2(r,p),rename=()->maintenance.save("BOOKSHELF",false,edit,actor("admin"));List<Object> outcome=renameFirst?contend(rename,move):contend(move,rename);if(renameFirst)assertEquals("PREVIEW_STALE",assertInstanceOf(BookCopyActionException.class,outcome.get(1)).reasonCode());else{assertFalse(outcome.get(0)instanceof Exception);assertEquals("并发新名称",current(c).path("placement").path("registeredLocation").path("bookshelfName").asText());}assertEquals(1,jdbc.queryForObject("SELECT layout_version FROM bookshelf WHERE id=?",Integer.class,a.shelf()));}
    }
    @Test void legacyBindingAndMoveAndAddressDeleteInBothCommitOrdersRespectSharedMutex()throws Exception{
        for(boolean maintenanceFirst:List.of(true,false))for(String operation:List.of("ASSIGN","CLEAR","DELETE")){Address a=address();Book b=book(1,1);BookCopy c=copy(b,"AVAILABLE",null);if(operation.equals("CLEAR"))maintenance.binding(a.id(),b.getId(),false,version(0),actor("admin"));long layout=operation.equals("CLEAR")?1:0;ObjectNode r=move(c,a.id());JsonNode p=preview2(r);Callable<Object> move=()->commit2(r,p),other=()->{if(operation.equals("DELETE"))maintenance.delete("LOCATION",a.id(),version(layout),actor("admin"));else maintenance.binding(a.id(),b.getId(),operation.equals("CLEAR"),version(layout),actor("admin"));return "done";};List<Object> out=maintenanceFirst?contend(other,move):contend(move,other);if(maintenanceFirst)assertEquals("PREVIEW_STALE",assertInstanceOf(BookCopyActionException.class,out.get(1)).reasonCode());else if(operation.equals("DELETE"))assertEquals("LOCATION_IN_USE",assertInstanceOf(BookCopyActionException.class,out.get(1)).reasonCode());else{assertEquals(a.id(),copies.selectById(c.getId()).getRegisteredLocationId());assertFalse(current(c).path("locationReferenceAnomaly").asBoolean());}}
    }
    @Test void childCreationAndParentDeletionNeverLeaveNewOrphans()throws Exception{
        for(boolean createFirst:List.of(true,false)){Address a=address();maintenance.delete("LOCATION",a.id(),version(0),actor("admin"));ObjectNode child=json.createObjectNode().put("storeyId",a.storey()).put("code","N"+unique()).put("status","EMPTY").put("reason","合成并发子项");Callable<Object> create=()->maintenance.save("LOCATION",true,child,actor("admin")),remove=()->{maintenance.delete("STOREY",a.storey(),version(0),actor("admin"));return "deleted";};List<Object> out=createFirst?contend(create,remove):contend(remove,create);assertInstanceOf(BookCopyActionException.class,out.get(1));assertEquals(createFirst?"LOCATION_IN_USE":"LOCATION_NOT_FOUND",((BookCopyActionException)out.get(1)).reasonCode());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM book_location l JOIN bookshelf_storey s ON s.id=l.storey_id WHERE l.deleted=0 AND s.deleted=1 AND s.id=?",Integer.class,a.storey()));}
    }
    @Test void sameCopyMovesBorrowingAndStateChangesCannotOverwriteEachOther()throws Exception{
        Address a=address(),other=address();Book b=book(1,1);BookCopy c=copy(b,"AVAILABLE",null);ObjectNode first=move(c,a.id()),second=move(c,other.id());JsonNode p1=preview2(first),p2=preview2(second);var out=contend(()->commit2(first,p1),()->commit2(second,p2));assertEquals("PREVIEW_STALE",assertInstanceOf(BookCopyActionException.class,out.get(1)).reasonCode());
        for(boolean borrowFirst:List.of(true,false)){Book title=book(1,1);BookCopy copy=copy(title,"AVAILABLE",null);ObjectNode r=move(copy,a.id());JsonNode p=preview2(r);BorrowRequest br=new BorrowRequest();br.setBookId(title.getId());br.setCopyId(copy.getId());br.setUserId(reader());Callable<Object> loan=()->borrows.borrow(br),move=()->commit2(r,p);var result=borrowFirst?contend(loan,move):contend(move,loan);if(borrowFirst)assertEquals("PREVIEW_STALE",assertInstanceOf(BookCopyActionException.class,result.get(1)).reasonCode());else assertInstanceOf(BorrowRecord.class,result.get(1));assertEquals("BORROWED",copies.selectById(copy.getId()).getStatus());}
        for(String action:List.of("WRITE_OFF","RESTORE")){Book title=book(1,1);BookCopy copy=copy(title,"AVAILABLE",null);if(action.equals("RESTORE")){ObjectNode off=request2("WRITE_OFF",copy);confirm(off,preview2(off),"admin");}ObjectNode change=request2(action,copy);if(action.equals("RESTORE"))restore(change,copy,"找回位置");JsonNode statePreview=preview2(change);if(action.equals("WRITE_OFF")){ObjectNode move=move(copy,a.id());JsonNode mp=preview2(move);var result=contend(()->commit2(change,statePreview),()->commit2(move,mp));assertEquals("PREVIEW_STALE",assertInstanceOf(BookCopyActionException.class,result.get(1)).reasonCode());}else{commit2(change,statePreview);assertNull(copies.selectById(copy.getId()).getRegisteredLocationId());}}
    }
    @Test void supplementalEventAndStructureAuditFailureRollBackEveryMutation()throws Exception{
        Address a=address();Book b=book(2,2);BookCopy x=copy(b,"AVAILABLE",null),y=copy(b,"AVAILABLE",null);ObjectNode move=request2("MOVE",x,y);for(JsonNode c:move.path("copies"))((ObjectNode)c).set("targetLocation",registered(a.id()));JsonNode p=preview2(move);var before=counts();var original=snapshot("book_copy",x.getId());jdbc.execute("CREATE TRIGGER fail_location_supp BEFORE INSERT ON book_copy_action_location FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic-supplement-failure'");try{assertThrows(org.springframework.dao.DataAccessException.class,()->commit2(move,p));}finally{jdbc.execute("DROP TRIGGER fail_location_supp");}assertEquals(before,counts());assertEquals(original,snapshot("book_copy",x.getId()));assertEquals("PREVIEWED",jdbc.queryForObject("SELECT state FROM book_copy_action_request WHERE id=?",String.class,p.path("requestId").asLong()));
        ObjectNode edit=shelfEdit(a.shelf(),"不得提交");var originalShelf=snapshot("bookshelf",a.shelf());jdbc.execute("CREATE TRIGGER fail_structure_audit BEFORE INSERT ON location_structure_event FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic-structure-failure'");try{assertThrows(org.springframework.dao.DataAccessException.class,()->maintenance.save("BOOKSHELF",false,edit,actor("admin")));}finally{jdbc.execute("DROP TRIGGER fail_structure_audit");}assertEquals(originalShelf,snapshot("bookshelf",a.shelf()));commit2(move,p);assertEquals(2,countFor("book_copy_action_location","after_location_id=?",a.id()));
    }
    @Test void changingStoreyParentAndDisabledTargetInvalidatePreviewWithoutChangingCopy()throws Exception{
        Address a=address(),other=address();Book b=book(1,1);BookCopy c=copy(b,"AVAILABLE",null);ObjectNode move=move(c,a.id());JsonNode p=preview2(move);ObjectNode parent=json.createObjectNode().put("id",a.storey()).put("expectedVersion",0).put("bookshelfId",other.shelf()).put("name","换父层").put("levelNum",3).put("capacity",1).put("status",1).put("reason","明确换父");maintenance.save("STOREY",false,parent,actor("admin"));assertThrows(BookCopyActionException.class,()->commit2(move,p));assertNull(copies.selectById(c.getId()).getRegisteredLocationId());ObjectNode next=move(c,a.id());JsonNode np=preview2(next);ObjectNode disabled=shelfEdit(other.shelf(),"停用目标").put("status",0);maintenance.save("BOOKSHELF",false,disabled,actor("admin"));assertEquals("PREVIEW_STALE",assertThrows(BookCopyActionException.class,()->commit2(next,np)).reasonCode());assertEquals(other.shelf(),currentAddress(a).path("bookshelfId").asLong());assertFalse(currentAddress(a).path("selectable").asBoolean());
    }
    private JsonNode currentAddress(Address a)throws Exception{return data(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/location-addresses/"+a.id()),"admin",200).path("address");}
    private Object commit2(ObjectNode input,JsonNode preview)throws Exception{return actions.confirmAny(preview.path("requestId").asLong(),json.treeToValue(confirmation(input,preview),ConfirmRequest.class),actor("admin"),true);}
    private List<Object> contend(Callable<Object> first,Callable<Object> second)throws Exception{
        ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch staged=new CountDownLatch(1),release=new CountDownLatch(1);Future<Object> one=pool.submit(()->new TransactionTemplate(transactions).execute(tx->{try{Object out=first.call();staged.countDown();if(!release.await(15,TimeUnit.SECONDS))throw new IllegalStateException("Missing release");return out;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}));
        try{assertTrue(staged.await(10,TimeUnit.SECONDS));Future<Object> two=pool.submit(()->{try{return second.call();}catch(BookCopyActionException e){return e;}});boolean waiting=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(System.nanoTime()<deadline){waiting=jdbc.queryForObject("SELECT COUNT(*) FROM performance_schema.data_lock_waits w JOIN performance_schema.data_locks l ON l.ENGINE=w.ENGINE AND l.ENGINE_LOCK_ID=w.REQUESTING_ENGINE_LOCK_ID WHERE l.OBJECT_SCHEMA=DATABASE()",Integer.class)>0;if(waiting)break;Thread.sleep(10);}assertTrue(waiting,"Must observe an actual InnoDB wait");assertFalse(two.isDone());release.countDown();return List.of(one.get(20,TimeUnit.SECONDS),two.get(20,TimeUnit.SECONDS));}finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}
    }
}
